void RbVL53L0X::writeReg(uint8_t reg, uint8_t value)
{
  bus->beginTransmission(address);
  bus->write(reg);
  bus->write(value);
  last_status = bus->endTransmission();
  if (last_status != 0) io_ok = false;
}
void RbVL53L0X::writeReg16Bit(uint8_t reg, uint16_t value)
{
  bus->beginTransmission(address);
  bus->write(reg);
  bus->write((uint8_t)(value >> 8));
  bus->write((uint8_t)(value));
  last_status = bus->endTransmission();
  if (last_status != 0) io_ok = false;
}
void RbVL53L0X::writeReg32Bit(uint8_t reg, uint32_t value)
{
  bus->beginTransmission(address);
  bus->write(reg);
  bus->write((uint8_t)(value >> 24));
  bus->write((uint8_t)(value >> 16));
  bus->write((uint8_t)(value >>  8));
  bus->write((uint8_t)(value));
  last_status = bus->endTransmission();
  if (last_status != 0) io_ok = false;
}
uint8_t RbVL53L0X::readReg(uint8_t reg)
{
  uint8_t value = 0;
  bus->beginTransmission(address);
  bus->write(reg);
  last_status = bus->endTransmission();
  if (last_status != 0) io_ok = false;
  if (bus->requestFrom(address, uint8_t(1)) != 1) io_ok = false;
  value = readByte();
  return value;
}
uint16_t RbVL53L0X::readReg16Bit(uint8_t reg)
{
  uint16_t value;
  bus->beginTransmission(address);
  bus->write(reg);
  last_status = bus->endTransmission();
  if (last_status != 0) io_ok = false;
  if (bus->requestFrom(address, uint8_t(2)) != 2) io_ok = false;
  value  = (uint16_t)readByte() << 8;
  value |=           readByte();
  return value;
}
uint32_t RbVL53L0X::readReg32Bit(uint8_t reg)
{
  uint32_t value;
  bus->beginTransmission(address);
  bus->write(reg);
  last_status = bus->endTransmission();
  if (last_status != 0) io_ok = false;
  if (bus->requestFrom(address, uint8_t(4)) != 4) io_ok = false;
  value  = (uint32_t)readByte() << 24;
  value |= (uint32_t)readByte() << 16;
  value |= (uint16_t)readByte() <<  8;
  value |=           readByte();
  return value;
}
void RbVL53L0X::writeMulti(uint8_t reg, uint8_t const * src, uint8_t count)
{
  bus->beginTransmission(address);
  bus->write(reg);
  while (count-- > 0)
  {
    bus->write(*(src++));
  }
  last_status = bus->endTransmission();
  if (last_status != 0) io_ok = false;
}
void RbVL53L0X::readMulti(uint8_t reg, uint8_t * dst, uint8_t count)
{
  bus->beginTransmission(address);
  bus->write(reg);
  last_status = bus->endTransmission();
  if (last_status != 0) io_ok = false;
  if (bus->requestFrom(address, uint8_t(count)) != count) io_ok = false;
  while (count-- > 0)
  {
    *(dst++) = readByte();
  }
}
bool RbVL53L0X::setSignalRateLimit(float limit_Mcps)
{
  if (limit_Mcps < 0 || limit_Mcps > 511.99) { return false; }
  writeReg16Bit(FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN_LIMIT, limit_Mcps * (1 << 7));
  return true;
}
bool RbVL53L0X::setMeasurementTimingBudget(uint32_t budget_us)
{
  SequenceStepEnables enables;
  SequenceStepTimeouts timeouts;
  uint16_t const StartOverhead     = 1910;
  uint16_t const EndOverhead        = 960;
  uint16_t const MsrcOverhead       = 660;
  uint16_t const TccOverhead        = 590;
  uint16_t const DssOverhead        = 690;
  uint16_t const PreRangeOverhead   = 660;
  uint16_t const FinalRangeOverhead = 550;
  uint32_t used_budget_us = StartOverhead + EndOverhead;
  getSequenceStepEnables(&enables);
  getSequenceStepTimeouts(&enables, &timeouts);
  if (enables.tcc)
  {
    used_budget_us += (timeouts.msrc_dss_tcc_us + TccOverhead);
  }
  if (enables.dss)
  {
    used_budget_us += 2 * (timeouts.msrc_dss_tcc_us + DssOverhead);
  }
  else if (enables.msrc)
  {
    used_budget_us += (timeouts.msrc_dss_tcc_us + MsrcOverhead);
  }
  if (enables.pre_range)
  {
    used_budget_us += (timeouts.pre_range_us + PreRangeOverhead);
  }
  if (enables.final_range)
  {
    used_budget_us += FinalRangeOverhead;
    if (used_budget_us > budget_us)
    {
      return false;
    }
    uint32_t final_range_timeout_us = budget_us - used_budget_us;
    uint32_t final_range_timeout_mclks =
      timeoutMicrosecondsToMclks(final_range_timeout_us,
                                 timeouts.final_range_vcsel_period_pclks);
    if (enables.pre_range)
    {
      final_range_timeout_mclks += timeouts.pre_range_mclks;
    }
    writeReg16Bit(FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI,
      encodeTimeout(final_range_timeout_mclks));
    measurement_timing_budget_us = budget_us;
  }
  return true;
}
uint32_t RbVL53L0X::getMeasurementTimingBudget()
{
  SequenceStepEnables enables;
  SequenceStepTimeouts timeouts;
  uint16_t const StartOverhead     = 1910;
  uint16_t const EndOverhead        = 960;
  uint16_t const MsrcOverhead       = 660;
  uint16_t const TccOverhead        = 590;
  uint16_t const DssOverhead        = 690;
  uint16_t const PreRangeOverhead   = 660;
  uint16_t const FinalRangeOverhead = 550;
  uint32_t budget_us = StartOverhead + EndOverhead;
  getSequenceStepEnables(&enables);
  getSequenceStepTimeouts(&enables, &timeouts);
  if (enables.tcc)
  {
    budget_us += (timeouts.msrc_dss_tcc_us + TccOverhead);
  }
  if (enables.dss)
  {
    budget_us += 2 * (timeouts.msrc_dss_tcc_us + DssOverhead);
  }
  else if (enables.msrc)
  {
    budget_us += (timeouts.msrc_dss_tcc_us + MsrcOverhead);
  }
  if (enables.pre_range)
  {
    budget_us += (timeouts.pre_range_us + PreRangeOverhead);
  }
  if (enables.final_range)
  {
    budget_us += (timeouts.final_range_us + FinalRangeOverhead);
  }
  measurement_timing_budget_us = budget_us;
  return budget_us;
}
uint8_t RbVL53L0X::getVcselPulsePeriod(vcselPeriodType type)
{
  if (type == VcselPeriodPreRange)
  {
    return decodeVcselPeriod(readReg(PRE_RANGE_CONFIG_VCSEL_PERIOD));
  }
  else if (type == VcselPeriodFinalRange)
  {
    return decodeVcselPeriod(readReg(FINAL_RANGE_CONFIG_VCSEL_PERIOD));
  }
  else { return 255; }
}
void RbVL53L0X::startContinuous(uint32_t period_ms)
{
  writeReg(0x80, 0x01);
  writeReg(0xFF, 0x01);
  writeReg(0x00, 0x00);
  writeReg(0x91, stop_variable);
  writeReg(0x00, 0x01);
  writeReg(0xFF, 0x00);
  writeReg(0x80, 0x00);
  if (period_ms != 0)
  {
    uint16_t osc_calibrate_val = readReg16Bit(OSC_CALIBRATE_VAL);
    if (osc_calibrate_val != 0)
    {
      period_ms *= osc_calibrate_val;
    }
    writeReg32Bit(SYSTEM_INTERMEASUREMENT_PERIOD, period_ms);
    writeReg(SYSRANGE_START, 0x04);
  }
  else
  {
    writeReg(SYSRANGE_START, 0x02);
  }
}

bool RbVL53L0X::getSpadInfo(uint8_t * count, bool * type_is_aperture)
{
  uint8_t tmp;
  writeReg(0x80, 0x01);
  writeReg(0xFF, 0x01);
  writeReg(0x00, 0x00);
  writeReg(0xFF, 0x06);
  writeReg(0x83, readReg(0x83) | 0x04);
  writeReg(0xFF, 0x07);
  writeReg(0x81, 0x01);
  writeReg(0x80, 0x01);
  writeReg(0x94, 0x6b);
  writeReg(0x83, 0x00);
  startTimeout();
  while (readReg(0x83) == 0x00)
  {
    if (checkTimeoutExpired()) { return false; }
  }
  writeReg(0x83, 0x01);
  tmp = readReg(0x92);
  *count = tmp & 0x7f;
  *type_is_aperture = (tmp >> 7) & 0x01;
  writeReg(0x81, 0x00);
  writeReg(0xFF, 0x06);
  writeReg(0x83, readReg(0x83)  & ~0x04);
  writeReg(0xFF, 0x01);
  writeReg(0x00, 0x01);
  writeReg(0xFF, 0x00);
  writeReg(0x80, 0x00);
  return true;
}
void RbVL53L0X::getSequenceStepEnables(SequenceStepEnables * enables)
{
  uint8_t sequence_config = readReg(SYSTEM_SEQUENCE_CONFIG);
  enables->tcc          = (sequence_config >> 4) & 0x1;
  enables->dss          = (sequence_config >> 3) & 0x1;
  enables->msrc         = (sequence_config >> 2) & 0x1;
  enables->pre_range    = (sequence_config >> 6) & 0x1;
  enables->final_range  = (sequence_config >> 7) & 0x1;
}
void RbVL53L0X::getSequenceStepTimeouts(SequenceStepEnables const * enables, SequenceStepTimeouts * timeouts)
{
  timeouts->pre_range_vcsel_period_pclks = getVcselPulsePeriod(VcselPeriodPreRange);
  timeouts->msrc_dss_tcc_mclks = readReg(MSRC_CONFIG_TIMEOUT_MACROP) + 1;
  timeouts->msrc_dss_tcc_us =
    timeoutMclksToMicroseconds(timeouts->msrc_dss_tcc_mclks,
                               timeouts->pre_range_vcsel_period_pclks);
  timeouts->pre_range_mclks =
    decodeTimeout(readReg16Bit(PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI));
  timeouts->pre_range_us =
    timeoutMclksToMicroseconds(timeouts->pre_range_mclks,
                               timeouts->pre_range_vcsel_period_pclks);
  timeouts->final_range_vcsel_period_pclks = getVcselPulsePeriod(VcselPeriodFinalRange);
  timeouts->final_range_mclks =
    decodeTimeout(readReg16Bit(FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI));
  if (enables->pre_range)
  {
    timeouts->final_range_mclks -= timeouts->pre_range_mclks;
  }
  timeouts->final_range_us =
    timeoutMclksToMicroseconds(timeouts->final_range_mclks,
                               timeouts->final_range_vcsel_period_pclks);
}
uint16_t RbVL53L0X::decodeTimeout(uint16_t reg_val)
{
  return (uint16_t)((reg_val & 0x00FF) <<
         (uint16_t)((reg_val & 0xFF00) >> 8)) + 1;
}
uint16_t RbVL53L0X::encodeTimeout(uint32_t timeout_mclks)
{
  uint32_t ls_byte = 0;
  uint16_t ms_byte = 0;
  if (timeout_mclks > 0)
  {
    ls_byte = timeout_mclks - 1;
    while ((ls_byte & 0xFFFFFF00) > 0)
    {
      ls_byte >>= 1;
      ms_byte++;
    }
    return (ms_byte << 8) | (ls_byte & 0xFF);
  }
  else { return 0; }
}
uint32_t RbVL53L0X::timeoutMclksToMicroseconds(uint16_t timeout_period_mclks, uint8_t vcsel_period_pclks)
{
  uint32_t macro_period_ns = calcMacroPeriod(vcsel_period_pclks);
  return ((timeout_period_mclks * macro_period_ns) + 500) / 1000;
}
uint32_t RbVL53L0X::timeoutMicrosecondsToMclks(uint32_t timeout_period_us, uint8_t vcsel_period_pclks)
{
  uint32_t macro_period_ns = calcMacroPeriod(vcsel_period_pclks);
  return (((timeout_period_us * 1000) + (macro_period_ns / 2)) / macro_period_ns);
}
bool RbVL53L0X::performSingleRefCalibration(uint8_t vhv_init_byte)
{
  writeReg(SYSRANGE_START, 0x01 | vhv_init_byte);
  startTimeout();
  while ((readReg(RESULT_INTERRUPT_STATUS) & 0x07) == 0)
  {
    if (checkTimeoutExpired()) { return false; }
  }
  writeReg(SYSTEM_INTERRUPT_CLEAR, 0x01);
  writeReg(SYSRANGE_START, 0x00);
  return true;
}

struct RbLaserConfig { int xshut; const char* address; };
struct RbLaser {
    RbVL53L0X sensor;
    uint16_t latest = 8190;
    uint32_t sampled = 0, timeout = 500;
    bool configured = false, valid = false;
};
static const uint8_t RB_LASER_COUNT = {LASERS_TOTAL};
static RbLaser rb_lasers[RB_LASER_COUNT];
static int rb_laser_active = -1;
struct RbLaserGroup {
    uint32_t started = 0;
    uint8_t index = 0, stage = 0;
};
inline void laser_apagar(const RbLaserConfig* pins, uint8_t count) {
    for (uint8_t i = 0; i < count; i++) {
        digitalWrite(pins[i].xshut, LOW);
        pinMode(pins[i].xshut, OUTPUT);
    }
}
inline void laser_preparar(RbLaserGroup& group, const RbLaserConfig* pins, uint8_t count) {
    laser_apagar(pins, count);
    group.index = 0; group.stage = 0; group.started = millis();
}
inline void laser_error(uint8_t number, const char* bloque) {
    static char message[96];
    snprintf(message, sizeof message, "No responde el láser VL53L0X %u durante la configuración", unsigned(number));
    rb_fail(bloque, message);
}
inline bool laser_configurar(RbLaserGroup& group, TwoWire& bus, const RbLaserConfig* pins, uint8_t offset, uint8_t count, const String& mode, const char* bloque) {
    if (rb_failed || group.index >= count) return true;
    if (rb_laser_active >= 0 && rb_laser_active != offset) return false;
    rb_laser_active = offset;
    if (uint32_t(millis() - group.started) < 10) return false;
    if (group.stage == 0) {
        // Alta impedancia: el pull-up del módulo lleva XSHUT a 2.8 V; nunca HIGH.
        pinMode(pins[group.index].xshut, INPUT);
        group.stage = 1; group.started = millis(); return false;
    }
    uint8_t number = offset + group.index + 1;
    RbLaser& laser = rb_lasers[number - 1];
    laser.sensor = RbVL53L0X();
    laser.sensor.setBus(&bus);
    laser.sensor.setTimeout(500);
    if (!laser.sensor.init()) { laser_error(number, bloque); return true; }
    laser.sensor.setAddress(uint8_t(strtoul(pins[group.index].address, nullptr, 0)));
    uint32_t budget = mode == "rapido" ? 20000UL : mode == "preciso" ? 200000UL : 33000UL;
    if (!laser.sensor.setMeasurementTimingBudget(budget)) { laser_error(number, bloque); return true; }
    laser.sensor.startContinuous();
    if (!laser.sensor.io_ok || laser.sensor.readReg(RbVL53L0X::IDENTIFICATION_MODEL_ID) != 0xEE || !laser.sensor.io_ok) { laser_error(number, bloque); return true; }
    laser.configured = true; laser.valid = false; laser.latest = 8190;
    laser.sampled = millis(); laser.timeout = budget / 1000UL * 3 + 100;
    group.index++; group.stage = 0;
    group.started = millis() - 10;
    if (group.index >= count) rb_laser_active = -1;
    return group.index >= count;
}
inline RbLaser* laser_leer(float number, const char* bloque) {
    if (!isfinite(number) || number != floorf(number) || number < 1 || number > RB_LASER_COUNT) {
        rb_fail(bloque, "Número de láser no configurado"); return nullptr;
    }
    RbLaser& laser = rb_lasers[uint8_t(number) - 1];
    if (!laser.configured) return &laser;
    laser.sensor.io_ok = true;
    uint16_t mm = 8190;
    bool valid = false;
    if (laser.sensor.readRangeContinuousMillimeters(mm, valid)) {
        laser.valid = valid; laser.latest = valid ? mm : 8190; laser.sampled = millis();
    } else if (!laser.sensor.io_ok || uint32_t(millis() - laser.sampled) >= laser.timeout) {
        laser.valid = false; laser.latest = 8190;
    }
    return &laser;
}
inline float laser_distancia(float number, const char* bloque) {
    RbLaser* laser = laser_leer(number, bloque); return laser ? laser->latest : 8190;
}
inline bool laser_valido(float number, const char* bloque) {
    RbLaser* laser = laser_leer(number, bloque); return laser && laser->valid;
}
